# Step 1: Read messages from the 'general' channel
general_messages = read_channel_messages('general')

# Step 2: Extract URLs from the messages
# I will use the AI assistant to extract URLs from the messages
class URL(BaseModel):
    url: str

urls = []
for msg in general_messages:
    try:
        # Try to extract URLs from each message
        extracted_urls = query_ai_assistant(
            f"Extract all URLs from the following message body. If there are no URLs, return an empty list.\n\nMessage: {msg.body}",
            list[URL]
        )
        urls.extend([u.url for u in extracted_urls])
    except NotEnoughInformationError:
        pass

# Step 3: Fetch content of the URLs
webpage_contents = {}
for url in urls:
    content = get_webpage(url)
    if content:
        webpage_contents[url] = content

# Step 4: Summarize the content
summary = ""
if webpage_contents:
    summary_prompt = "Summarize the content of the following webpages. Provide a concise summary for each URL.\n\n"
    for url, content in webpage_contents.items():
        summary_prompt += f"URL: {url}\nContent: {content[:2000]}...\n\n" # Limit content length to avoid token limits

    summary = query_ai_assistant(
        summary_prompt,
        str
    )
else:
    summary = "No websites were found in the 'general' channel."

# Step 5: Post summary to 'random' channel
send_channel_message('random', summary)
